from collections import Counter

def topKFrequent(nums, k):
    count = Counter(nums)
    buckets = [[] for _ in range(len(nums) + 1)]   # index = frequency
    for v, c in count.items():
        buckets[c].append(v)
    out = []
    for c in range(len(nums), 0, -1):              # highest frequency first
        for v in buckets[c]:
            out.append(v)
            if len(out) == k:
                return out
    return out

