def lengthOfLongestSubstring(s):
    last = {}                       # char -> last index seen
    left = best = 0
    for i, ch in enumerate(s):
        if last.get(ch, -1) >= left:
            left = last[ch] + 1     # jump past the previous copy
        last[ch] = i
        best = max(best, i - left + 1)
    return best

