def merge(intervals):
    intervals.sort(key=lambda p: p[0])
    out = [intervals[0][:]]
    for s, e in intervals[1:]:
        if s <= out[-1][1]:                  # touching counts
            out[-1][1] = max(out[-1][1], e)  # swallow, maybe extend
        else:
            out.append([s, e])
    return out

