from bisect import bisect_left

def lengthOfLIS(nums):
    tails = []          # tails[i] = smallest tail of an increasing run of length i+1
    for x in nums:
        i = bisect_left(tails, x)   # first tail >= x (strict increase)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

